import{_ as e,o,c as n,ag as i}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Part 24 — Engineering Practice & Communication","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_24_Engineering_Practice.md","filePath":"todo/study_plan/parts/Part_24_Engineering_Practice.md"}'),r={name:"todo/study_plan/parts/Part_24_Engineering_Practice.md"};function s(a,t,d,l,c,u){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="part-24-—-engineering-practice-communication" tabindex="-1">Part 24 — Engineering Practice &amp; Communication <a class="header-anchor" href="#part-24-—-engineering-practice-communication" aria-label="Permalink to &quot;Part 24 — Engineering Practice &amp; Communication&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Light touch — soft skills; practice ongoing, no dedicated week. <strong>Budget: ~1-2 hrs (overflow slot).</strong></p></blockquote><h2 id="_24-engineering-practice-communication-—-topic-inventory" tabindex="-1">24 Engineering Practice &amp; Communication — topic inventory <a class="header-anchor" href="#_24-engineering-practice-communication-—-topic-inventory" aria-label="Permalink to &quot;24 Engineering Practice &amp; Communication — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Writing design docs — context, goals, non-goals, alternatives, tradeoffs</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>2</td><td>RFC process, design reviews</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Code review etiquette — what&#39;s worth commenting on</td><td>🔴 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Technical writing — clarity over cleverness</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>Mentoring juniors</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Estimation, scoping, breakdown into stories</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>Sprint hygiene, async communication</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Influence without authority (cross-team work)</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Tech talks, brown bags</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Blog writing, open source contributions</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~5.25 hrs</td><td>~0.5 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~9.0 hrs</td><td>~0.85 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~10.5 hrs</td><td>~0.95 wk</td><td></td></tr></tbody></table><blockquote><p>This Part is soft-skills-heavy. Time estimates assume <em>reading + reflecting + producing artifacts</em> (a design doc, a brag log, a code review checklist). The real learning is over months of practice, not study hours.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk through the structure of a design doc you&#39;d write for a substantial feature. <ul><li><strong>Why asked:</strong> Senior signaling. Sections: (1) Context — why this matters now. (2) Goals + non-goals — explicit scope boundary. (3) Proposed design — what we&#39;ll build, with key decisions called out. (4) Alternatives considered — what we rejected and why. (5) Tradeoffs — what we&#39;re giving up. (6) Risks + mitigations. (7) Rollout plan. (8) Open questions. Always one page of TL;DR up top.</li></ul></li><li><strong>Q:</strong> What&#39;s worth commenting on in a code review? <ul><li><strong>Why asked:</strong> Senior-judgment signal. Worth: correctness bugs, missing edge cases, security issues, performance traps, unclear naming, missing tests for non-trivial logic, violations of project conventions. Not worth: style preferences (use linter), micro-optimizations, &quot;I&#39;d write it differently&quot; (without reason). Bias toward asking questions over making demands.</li></ul></li><li><strong>Q:</strong> How do you estimate a substantial project (3+ months)? <ul><li><strong>Why asked:</strong> Senior planning. Break into known/unknown. For known parts: bottom-up estimate from comparable past work. For unknown: spike + estimate after. Add 50% buffer for integration, debugging, doc, surprises. Communicate range, not point. Re-estimate at milestones.</li></ul></li><li><strong>Q:</strong> Walk through influencing a cross-team decision without authority. <ul><li><strong>Why asked:</strong> Staff-engineer signal. (1) Understand their constraints first. (2) Frame in terms of their goals, not yours. (3) Provide data, not opinions. (4) Propose, don&#39;t demand. (5) Offer to help with the work. (6) Identify the actual decision-maker. (7) Persist patiently. (8) Accept &quot;no&quot; gracefully when reasonable.</li></ul></li><li><strong>Q:</strong> Mentoring juniors — what&#39;s your model? <ul><li><strong>Why asked:</strong> Promotion signal. Show vs. tell: pair on real work, give them context for <em>why</em> you&#39;re doing X, let them try and fail safely. Code reviews as teaching moments. Document the &quot;this is why we don&#39;t do that&quot; knowledge that&#39;s tribal. Don&#39;t take over their work; make them stronger.</li></ul></li><li><strong>Q:</strong> How do you write a brag doc / weekly notes? <ul><li><strong>Why asked:</strong> Promotion infrastructure. Brag doc: live document, append weekly. For each item: situation, action, outcome (STAR-style), with explicit impact. Notes: meeting decisions, problems solved, mentoring instances. Build over 6-12 months — your promotion case writes itself.</li></ul></li><li><strong>Q:</strong> Async communication — what&#39;s the senior pattern? <ul><li><strong>Why asked:</strong> Modern remote-friendly skill. Write more, meet less. Write decisions in writing-first form (so they&#39;re searchable). Document context in shared docs, not Slack threads (lost forever). For PRs / RFCs, expect reviewers to think → comment, not respond instantly. Batch your communication windows.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your design doc gets minimal feedback in review. You take that as approval. Two weeks later, a senior says &quot;I had concerns I never raised.&quot; What went wrong? <ul><li><strong>Gotcha:</strong> Silent review ≠ approval. Best practice: explicitly ask for concerns (&quot;what&#39;s the worst case I&#39;m missing?&quot;). Cold-call specific reviewers for input. Set a deadline by which silence counts as approval. Document who reviewed.</li></ul></li><li><strong>Q:</strong> You wrote a clever solution in 20 lines. A junior asks &quot;why?&quot; and you can&#39;t explain it concisely. What&#39;s the problem? <ul><li><strong>Gotcha:</strong> Cleverness is a tax. If you can&#39;t explain, others can&#39;t maintain. Senior signal: prefer obvious code over clever code, even when slightly longer. Or — if cleverness is necessary — write a multi-line comment explaining the <em>why</em> (not the what).</li></ul></li><li><strong>Q:</strong> You estimated 3 weeks. You&#39;re 4 weeks in. You think 2 more weeks. What do you do? <ul><li><strong>Gotcha:</strong> Tell the team NOW, not at week 6. Slipping by 50%+ and only telling at the deadline kills trust. The honest pattern: (1) at slip-detect, communicate ASAP, (2) explain the surprise, (3) offer revised estimate, (4) ask &quot;do we still want this, scope down, or kill?&quot; Re-decide with new info.</li></ul></li><li><strong>Q:</strong> Cross-team work — you delivered, they didn&#39;t. The combined feature didn&#39;t ship. Where&#39;s the failure? <ul><li><strong>Gotcha:</strong> Senior failure mode: you delivered &quot;your part&quot; but didn&#39;t ensure the integrated outcome. Senior pattern: take ownership of the <em>outcome</em>, not just your slice. Track the other team&#39;s progress, escalate blockers early, offer help. &quot;I did my part&quot; doesn&#39;t ship features.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Write a real design doc</strong> (~3 hrs) — for an actual upcoming KYC platform decision. Run through the full structure. Submit for review. Iterate based on feedback. The artifact AND the review experience are both the value.</li><li><strong>Code review style guide</strong> (~2 hrs) — write down your team&#39;s (or your own) code-review expectations. What to comment on, what to skip, tone, decision rights. Useful for onboarding juniors.</li><li><strong>Brag doc + weekly notes habit</strong> (~ongoing) — start a markdown file. Append weekly with impact-shaped entries. Six months in, you&#39;ll have promotion ammunition.</li></ul><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Design doc structure?</strong> A. Context → Goals + non-goals → Proposed design → Alternatives considered → Tradeoffs → Risks + mitigations → Rollout plan → Open questions. One-page TL;DR up top.</p><p><strong>Q. Code review — what&#39;s worth commenting on?</strong> A. Correctness, security, performance traps, unclear naming, missing tests for non-trivial logic, project-convention violations. NOT style preferences (linter), or &quot;I&#39;d write it differently&quot; without reason.</p><p><strong>Q. Estimation — range vs point?</strong> A. Always range. Point estimates create false confidence. &quot;3-5 weeks, depending on how the vendor integration goes&quot; is better than &quot;4 weeks.&quot; Re-estimate at milestones.</p><p><strong>Q. Brag doc structure per entry?</strong> A. STAR: Situation, Task, Action, Result. Plus explicit impact statement (saved $X / improved Y by Z%). Quarterly review to clean up weak entries.</p><p><strong>Q. Influence without authority — first step?</strong> A. Understand their constraints. Frame your ask in terms of their goals. Provide data, not opinions. Propose, don&#39;t demand.</p><p><strong>Q. Async communication senior pattern?</strong> A. Write decisions in long-form (searchable). Document context in shared docs (not Slack threads). PRs and RFCs operate on respond-when-thoughtful cadence, not real-time. Batch communication windows.</p>',20)])])}const m=e(r,[["render",s]]);export{g as __pageData,m as default};
